import os
import shutil
from pathlib import Path


def read_file(file_path):
    try:
        with open(file_path) as f:
            return f.read()
    except (FileNotFoundError, PermissionError, OSError) as e:
        return str(e)


def write_file(file_path, data):
    p = Path(file_path)
    original = read_file(file_path)
    if isinstance(original, str):
        backup_path = p.with_name(f"{p.stem}_copy{p.suffix}")
        backup_path.write_text(original)
    p.write_text(data)
    return f"wrote {len(data)} chars to {file_path}"


def list_files(dir_path):
    try:
        return os.listdir(dir_path)
    except (FileNotFoundError, NotADirectoryError, PermissionError, OSError) as e:
        return str(e)


def get_current_dir():
    try:
        return str(Path.cwd())
    except OSError as e:
        return str(e)


def search_files(target, dir_path=""):
    """Search for a substring (or regex) inside files. Empty dir_path -> cwd."""
    base = Path(dir_path).expanduser() if dir_path else Path.cwd()
    try:
        results = []
        for path in sorted(base.rglob("*")):
            if path.is_file():
                try:
                    with open(path, "r", encoding="utf-8", errors="ignore") as f:
                        content = f.read()
                except (OSError, PermissionError):
                    continue
                hits = [ln.strip() for ln in content.splitlines() if target in ln]
                if hits:
                    rel = str(path.relative_to(base))
                    results.append(f"{rel}:\n  {hits}")
        msg = f"Found matches in {len(results)} file(s) under {base}"
        if results:
            msg += ":\n    " + "\n    ".join(results)
        return msg
    except (OSError, PermissionError, ValueError) as e:
        return str(e)


def delete_file(file_path):
    p = Path(file_path).expanduser()
    try:
        if not p.exists():
            return f"source does not exist: {file_path}"
        if p.is_dir():
            shutil.rmtree(p)
        else:
            p.unlink()
        return f"deleted {file_path}"
    except (FileNotFoundError, PermissionError, OSError) as e:
        return str(e)


def mkdir(dir_path):
    p = Path(dir_path).expanduser()
    try:
        p.mkdir(parents=True, exist_ok=True)
        return f"created directory {p}"
    except (OSError, PermissionError) as e:
        return str(e)


def move_file(src, dest):
    s = Path(src).expanduser()
    d = Path(dest).expanduser()
    try:
        if not s.exists():
            return f"source does not exist: {src}"
        d.parent.mkdir(parents=True, exist_ok=True)
        s.rename(d)
        return f"moved {src} to {dest}"
    except (FileNotFoundError, PermissionError, OSError) as e:
        return str(e)


def copy_file(src, dest):
    s = Path(src).expanduser()
    d = Path(dest).expanduser()
    try:
        if not s.exists():
            return f"source does not exist: {src}"
        d.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(s, d)
        return f"copied {src} to {dest}"
    except (FileNotFoundError, PermissionError, OSError) as e:
        return str(e)


def count_lines(file_path):
    p = Path(file_path).expanduser()
    try:
        text = p.read_text(encoding="utf-8", errors="ignore")
        lines = text.splitlines()
        words = len(text.split())
        chars = len(text)
        return f"lines={len(lines)} words={words} chars={chars}"
    except (FileNotFoundError, PermissionError, OSError) as e:
        return str(e)


